import 'package:flutter/material.dart';
import 'view_models/agenda_view_model.dart';
class AgendaScreen extends StatefulWidget { const AgendaScreen({super.key, required this.viewModel}); final AgendaViewModel viewModel; @override State<AgendaScreen> createState() => _AgendaScreenState(); }
class _AgendaScreenState extends State<AgendaScreen> { @override void initState() { super.initState(); widget.viewModel..addListener(_refresh)..load(); } void _refresh() { if (mounted) setState(() {}); } @override void dispose() { widget.viewModel.removeListener(_refresh); super.dispose(); }
  @override Widget build(BuildContext context) { if (widget.viewModel.loading && widget.viewModel.items.isEmpty) return const Center(child: CircularProgressIndicator()); return RefreshIndicator(onRefresh: () => widget.viewModel.load(), child: ListView(padding: const EdgeInsets.all(16), children: [Text('Agenda', style: Theme.of(context).textTheme.headlineSmall), const SizedBox(height: 12), if (widget.viewModel.error != null) Text(widget.viewModel.error!), ...widget.viewModel.items.map((item) => Card(child: ListTile(leading: const Icon(Icons.event), title: Text('${item.time} • ${item.clientName}'), subtitle: Text('${item.date} · ${item.serviceName} · ${item.status}'), trailing: item.status == 'finalizado' ? const Icon(Icons.check_circle, color: Colors.green) : TextButton(onPressed: () => widget.viewModel.finish(item), child: const Text('Finalizar'))))) ])); }
}
